/** Builds one pack via the dmtools CLI. Returns the produced zip path. */
function buildPack(agent, version) {
  execFileSync(
    'dmtools',
    ['compile', `${agent}.json`, '--agent-root', ROOT, '--version', version, '--out', OUT_DIR, '--include', 'instructions', '--include', 'prompts'],
