  const files = manifest.files || [];
  if (files.length === 0) throw new Error(`manifest.json in ${zipPath} has no files`);
  for (const f of files) {
    const bytes = execSync(`unzip -p ${JSON.stringify(zipPath)} ${JSON.stringify(f.path)}`);
